#!/usr/bin/env bash
# Runs only inside the disposable Ubuntu chroot generated by build-live-iso.sh.
set -Eeuo pipefail
export DEBIAN_FRONTEND=noninteractive
apt-get -o Acquire::Retries=3 update
apt-get -o Acquire::Retries=3 install -y --no-install-recommends \
  linux-image-generic initramfs-tools casper systemd-sysv dbus-user-session \
  sudo gdm3 gnome-shell gnome-session gnome-settings-daemon gnome-keyring \
  gnome-control-center nautilus gvfs gvfs-backends xdg-user-dirs \
  ptyxis network-manager wpasupplicant xwayland pipewire pipewire-pulse wireplumber \
  xdg-desktop-portal-gnome adwaita-icon-theme fonts-noto-core fonts-dejavu-core \
  dconf-cli gsettings-desktop-schemas plymouth ca-certificates python3 python3-gi gir1.2-gtk-4.0 gir1.2-adw-1
useradd -m -s /bin/bash -G sudo,audio,video,plugdev localzet
# Live session only: empty password allows GDM automatic login; SSH is not installed.
# Do not copy this account policy into an installed system.
passwd -d localzet
# Ephemeral Live account only. Installed systems MUST NOT inherit this sudo rule.
install -d -m 0755 /etc/sudoers.d
printf 'localzet ALL=(ALL) NOPASSWD:ALL\n' > /etc/sudoers.d/90-localzet-live
chmod 0440 /etc/sudoers.d/90-localzet-live
install -d /etc/gdm3
cat > /etc/gdm3/custom.conf <<'GDM'
[daemon]
AutomaticLoginEnable=True
AutomaticLogin=localzet
GDM
install -d /etc/dconf/profile
printf 'user-db:user\nsystem-db:localzet\n' > /etc/dconf/profile/user
install -d /etc/dconf/db/localzet.d
cat > /etc/dconf/db/localzet.d/00-defaults <<'DCONF'
[org/gnome/desktop/interface]
color-scheme='prefer-dark'
[org/gnome/desktop/background]
picture-uri='file:///usr/share/backgrounds/localzet/aurora.svg'
picture-uri-dark='file:///usr/share/backgrounds/localzet/aurora.svg'
[org/gnome/shell]
enabled-extensions=['localzet-shell@localzet.com']
# The temporary Live user has no password. Avoid an unusable locked desktop.
[org/gnome/desktop/session]
idle-delay=uint32 0
[org/gnome/desktop/screensaver]
lock-enabled=false
DCONF
dconf update
systemctl set-default graphical.target
systemctl enable NetworkManager.service || true
systemctl enable gdm3.service || true
systemctl enable localzet-boot-diagnostics.service
systemctl enable localzet-live-seat-guard.service
# P1 Live ISO only: GDM sometimes leaves Plymouth's quit-wait unit blocking
# graphical.target during slow software-emulated boots.
# Revisit splash handover before creating a disk installer.
systemctl mask plymouth-quit-wait.service
# casper currently requires an initramfs capable of discovering ISO squashfs.
KERNEL="$(find /boot -maxdepth 1 -type f -name 'vmlinuz-*' | sort -V | tail -1)"
VERSION="${KERNEL##*/vmlinuz-}"
if [[ ! -s "/boot/initrd.img-$VERSION" ]]; then
  update-initramfs -c -k "$VERSION"
else
  update-initramfs -u -k "$VERSION"
fi
if ! lsinitramfs "/boot/initrd.img-$VERSION" | grep -Eq '(^|/)casper($|/)'; then
  echo 'casper hook not found in generated initramfs' >&2
  exit 1
fi
apt-get clean
rm -rf /var/lib/apt/lists/* /var/cache/apt/archives/*.deb
